      children: (0,jsx_runtime.jsx)(_components.code, {
        className: "language-python",
        children: "from azure.search.documents import SearchClient\r\nfrom azure.search.documents.indexes import SearchIndexClient\r\nfrom azure.search.documents.indexes.models import (\r\n    SearchIndex,\r\n    SimpleField,\r\n    SearchableField,\r\n    VectorSearch,\r\n    HnswAlgorithmConfiguration,\r\n    VectorSearchAlgorithmKind,\r\n    VectorSearchProfile,\r\n)\r\nfrom azure.core.credentials import AzureKeyCredential\r\n\r\n# Create vector index\r\nindex_client = SearchIndexClient(\r\n    endpoint=os.environ[\"SEARCH_ENDPOINT\"],\r\n    credential=AzureKeyCredential(os.environ[\"SEARCH_KEY\"]),\r\n)\r\n\r\nindex = SearchIndex(\r\n    name=\"ml-docs\",\r\n    fields=[\r\n        SimpleField(name=\"id\", type=\"Edm.String\", key=True),\r\n        SearchableField(name=\"title\", type=\"Edm.String\"),\r\n        SearchableField(name=\"content\", type=\"Edm.String\"),\r\n        SearchField(  # Vector field\r\n            name=\"content_vector\",\r\n            type=\"Collection(Edm.Single)\",\r\n            vector_search_dimensions=1536,\r\n            vector_search_profile_name=\"my-vector-config\",\r\n        ),\r\n    ],\r\n    vector_search=VectorSearch(\r\n        algorithms=[\r\n            HnswAlgorithmConfiguration(\r\n                name=\"my-algo\",\r\n                kind=VectorSearchAlgorithmKind.HNSW,\r\n                parameters={\r\n                    \"m\": 4,\r\n                    \"efConstruction\": 400,\r\n                    \"efSearch\": 500,\r\n                }\r\n            )\r\n        ],\r\n        profiles=[\r\n            VectorSearchProfile(\r\n                name=\"my-vector-config\",\r\n                algorithm_configuration_name=\"my-algo\",\r\n            )\r\n        ]\r\n    ),\r\n)\r\n\r\nindex_client.create_or_update_index(index)\r\n\r\n# Search with vectors\r\nsearch_client = SearchClient(\r\n    endpoint=os.environ[\"SEARCH_ENDPOINT\"],\r\n    index_name=\"ml-docs\",\r\n    credential=AzureKeyCredential(os.environ[\"SEARCH_KEY\"]),\r\n)\r\n\r\n# Generate query embedding\r\noai_client = AzureOpenAI(...)\r\nquery_embedding = oai_client.embeddings.create(\r\n    model=\"text-embedding-ada-002\",\r\n    input=\"How to deploy ML models to production?\"\r\n).data[0].embedding\r\n\r\nresults = search_client.search(\r\n    search_text=None,\r\n    vector_queries=[{\r\n        \"vector\": query_embedding,\r\n        \"k\": 5,\r\n        \"fields\": \"content_vector\",\r\n    }],\r\n    select=[\"title\", \"content\"],\r\n)\r\n\r\nfor result in results:\r\n    print(f\"Score: {result['@search.score']:.3f} - {result['title']}\")\n"
      })
